import java.io.*;
import java.util.*;

public class D {
    public static void main(String[] args) {
        new Solver();
    }

    static class Solver {
        IO io;

        public Solver() {
            io = new IO();
            try {
                runProgram();
            } catch (RuntimeException e) {
                if (!"Clean exit".equals(e.getMessage())) {
                    throw e;
                }
            } finally {
                io.close();
            }
        }

        void runProgram() {
            long n = io.nextLong();
            long m = io.nextLong();
            if (m < n) {
                long temp = m;
                m = n;
                n = temp;
            }

            if (n == 1) {
                io.println(solveForOne(m));
                return;
            }
            if (n == 2) {
                if (m < 3) io.println(0);
                else if (m == 3) io.println(4);
                else if (m == 7) io.println(12);
                else io.println(2 * m);
                return;
            }

            io.println(2 * (n * m / 2));
        }

        long solveForOne(long m) {
            long res = 6 * (m / 6);
            if (m % 6 == 5) res += 4;
            else if (m % 6 == 4) res += 2;
            return res;
        }
    }

    static class IO extends PrintWriter {
        private InputStreamReader inputReader;
        private static final int BUFFER_SIZE = 1 << 15;
        private char[] buffer;
        private int index;
        private int length;
        private StringBuilder sb;

        public IO() {
            super(new BufferedOutputStream(System.out));
            inputReader = new InputStreamReader(System.in);
            buffer = new char[BUFFER_SIZE];
            index = 0;
            length = 0;
            sb = new StringBuilder();
        }

        private void fillBuffer() throws IOException {
            length = inputReader.read(buffer, 0, BUFFER_SIZE);
            index = 0;
        }

        private boolean hasNextChar() throws IOException {
            if (index >= length) {
                fillBuffer();
            }
            return length > 0;
        }

        private boolean isWhitespace(char c) {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
        }

        private void skipWhitespace() throws IOException {
            while (true) {
                if (!hasNextChar()) break;
                if (!isWhitespace(buffer[index])) break;
                index++;
            }
        }

        public String next() {
            try {
                sb.setLength(0);
                skipWhitespace();
                int startIdx = index;
                while (true) {
                    if (!hasNextChar()) break;
                    if (isWhitespace(buffer[index])) break;
                    index++;
                }
                sb.append(buffer, startIdx, index - startIdx);
                return sb.toString();
            } catch (IOException e) {
                throw new RuntimeException("IO.next: IOException");
            }
        }

        public long nextLong() {
            try {
                long res = 0;
                boolean positive = true;
                skipWhitespace();
                if (buffer[index] == '-') {
                    positive = false;
                    index++;
                }
                while (true) {
                    if (!hasNextChar()) break;
                    if (isWhitespace(buffer[index])) break;
                    res = res * 10 + (buffer[index] - '0');
                    index++;
                }
                return positive ? res : -res;
            } catch (IOException e) {
                throw new RuntimeException("IO.nextLong: IOException");
            }
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }
